DECLARE
  l_graph VARCHAR2(128); l_state VARCHAR2(16); l_hash VARCHAR2(64);
  l_old_hash VARCHAR2(64); l_existing CLOB; l_batch NUMBER; l_stage_count NUMBER;
BEGIN
  SELECT setting_value INTO l_graph FROM kcv_settings WHERE setting_key='DATASET_LOAD_GRAPH';
  SELECT state,graph_hash INTO l_state,l_hash FROM kcv_graph_runs WHERE graph_name=l_graph;
  IF l_hash<>'397da9d9f22e3188e89a7c6671d34e1edfef7528a6c106025a63e9a3a4f8b041' THEN RAISE_APPLICATION_ERROR(-20005,'Another dataset load replaced this run'); END IF;
  IF l_state<>'READY' THEN
    SELECT TO_NUMBER(setting_value) INTO l_batch FROM kcv_settings WHERE setting_key='DATASET_LOAD_BATCH';
    IF l_batch<>361 THEN RAISE_APPLICATION_ERROR(-20006,'Previous dataset batch failed; rerun the full loader'); END IF;
UPDATE kcv_graph_runs SET state='READY' WHERE graph_name=l_graph;
UPDATE kcv_settings SET setting_value='362' WHERE setting_key='DATASET_LOAD_BATCH';
DBMS_OUTPUT.PUT_LINE('Dataset batch 362/362 complete');
COMMIT;
END IF;
END;
/
DECLARE
  l_graph VARCHAR2(128); l_state VARCHAR2(16); l_hash VARCHAR2(64);
BEGIN
SELECT setting_value INTO l_graph FROM kcv_settings WHERE setting_key='DATASET_LOAD_GRAPH';
SELECT state,graph_hash INTO l_state,l_hash FROM kcv_graph_runs WHERE graph_name=l_graph;
IF l_state<>'READY' OR l_hash<>'397da9d9f22e3188e89a7c6671d34e1edfef7528a6c106025a63e9a3a4f8b041' THEN RAISE_APPLICATION_ERROR(-20007,'Dataset is incomplete; active graph unchanged'); END IF;
MERGE INTO kcv_settings t USING (SELECT 'ACTIVE_GRAPH' setting_key FROM dual) s ON(t.setting_key=s.setting_key) WHEN MATCHED THEN UPDATE SET t.setting_value=l_graph WHEN NOT MATCHED THEN INSERT(setting_key,setting_value) VALUES('ACTIVE_GRAPH',l_graph);
COMMIT; DBMS_OUTPUT.PUT_LINE('Active graph: '||l_graph);
END;
/
SELECT setting_value AS active_graph FROM kcv_settings WHERE setting_key='ACTIVE_GRAPH'
/
